import React, { useState, useMemo } from "react";
import { DollarSign, Calendar, TrendingUp, Layers, Trash2 } from "lucide-react";
import "./Tracker.css";

const CATEGORIES = [
  { name: "Food", color: "#F4A259" },
  { name: "Travel", color: "#5B8DEF" },
  { name: "Shopping", color: "#9B72CF" },
  { name: "Bills", color: "#4CAF8C" },
  { name: "Health", color: "#EF6C6C" },
  { name: "Other", color: "#8C97A8" },
];

function categoryColor(name) {
  return CATEGORIES.find((c) => c.name === name)?.color || "#8C97A8";
}

function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

function formatDate(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" });
}

export default function ExpenseTracker() {
  const [expenses, setExpenses] = useState([]);
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [description, setDescription] = useState("");
  const [date, setDate] = useState(todayISO());
  const [error, setError] = useState("");

  const stats = useMemo(() => {
    let total = 0, month = 0, week = 0, today = 0;
    const nowTime = new Date();
    const startOfWeek = new Date(nowTime);
    startOfWeek.setDate(nowTime.getDate() - nowTime.getDay());
    startOfWeek.setHours(0, 0, 0, 0);

    expenses.forEach((e) => {
      const d = new Date(e.date + "T00:00:00");
      total += e.amount;
      if (d.getMonth() === nowTime.getMonth() && d.getFullYear() === nowTime.getFullYear()) {
        month += e.amount;
      }
      if (d >= startOfWeek) {
        week += e.amount;
      }
      if (e.date === todayISO()) {
        today += e.amount;
      }
    });
    return { total, month, week, today };
  }, [expenses]);

  function handleAdd(e) {
    e.preventDefault();
    const value = parseFloat(amount);
    if (!value || value <= 0) {
      setError("Enter a valid amount");
      return;
    }
    if (!category) {
      setError("Choose a category");
      return;
    }
    setExpenses((prev) => [
      {
        id: Date.now(),
        amount: value,
        category,
        description: description.trim() || category,
        date,
      },
      ...prev,
    ]);
    setAmount("");
    setCategory("");
    setDescription("");
    setDate(todayISO());
    setError("");
  }

  function removeExpense(id) {
    setExpenses((prev) => prev.filter((e) => e.id !== id));
  }

  const statCards = [
    { label: "Total Expense", value: stats.total, icon: DollarSign },
    { label: "This Month", value: stats.month, icon: Calendar },
    { label: "This Week", value: stats.week, icon: TrendingUp },
    { label: "Today", value: stats.today, icon: Layers },
  ];

  return (
    <div className="tracker-page">
      <div className="tracker-container">
        {/* Header */}
        <div className="tracker-header">
          <h1 className="tracker-title">Expense Tracker</h1>
          <p className="tracker-subtitle">Keep track of your spending and manage your budget</p>
        </div>

        {/* Stat cards */}
        <div className="stat-grid">
          {statCards.map(({ label, value, icon: Icon }) => (
            <div key={label} className="stat-card">
              <div>
                <p className="stat-label">{label}</p>
                <p className="stat-value">${value.toFixed(2)}</p>
              </div>
              <div className="stat-icon">
                <Icon size={16} />
              </div>
            </div>
          ))}
        </div>

        <div className="main-grid">
          {/* Add expense form */}
          <div className="card">
            <h2 className="card-title">Add New Expense</h2>
            <form onSubmit={handleAdd} className="form">
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Amount ($)</label>
                  <input
                    type="number"
                    step="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                    className="form-input"
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Category</label>
                  <select
                    value={category}
                    onChange={(e) => setCategory(e.target.value)}
                    className="form-input"
                  >
                    <option value="">Select category</option>
                    {CATEGORIES.map((c) => (
                      <option key={c.name} value={c.name}>
                        {c.name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label">Description</label>
                <input
                  type="text"
                  placeholder="What did you spend on?"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="form-label">Date</label>
                <input
                  type="date"
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="form-input"
                />
              </div>

              {error && <p className="form-error">{error}</p>}

              <button type="submit" className="submit-btn">
                Add Expense
              </button>
            </form>
          </div>

          {/* Recent expenses */}
          <div className="card">
            <h2 className="card-title">Recent Expenses</h2>
            {expenses.length === 0 ? (
              <div className="empty-state">
                <DollarSign size={28} className="empty-icon" />
                <p className="empty-text">No expenses yet. Add your first expense above!</p>
              </div>
            ) : (
              <ul className="expense-list">
                {expenses.map((e) => (
                  <li key={e.id} className="expense-item">
                    <div className="expense-left">
                      <span
                        className="expense-dot"
                        style={{ backgroundColor: categoryColor(e.category) }}
                      />
                      <div>
                        <p className="expense-desc">{e.description}</p>
                        <p className="expense-meta">
                          {e.category} · {formatDate(e.date)}
                        </p>
                      </div>
                    </div>
                    <div className="expense-right">
                      <span className="expense-amount">${e.amount.toFixed(2)}</span>
                      <button
                        onClick={() => removeExpense(e.id)}
                        className="delete-btn"
                        aria-label="Delete expense"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
